/** Types of docs/ai-ui/catalog.json (generated by tools/ai-ui/build-catalog.mjs). */

/** A prop's type as a JSON-Schema subset, with `x-kind` for what JSON cannot say. */
export type PropSchema = {
  type?: "string" | "number" | "boolean" | "null" | "array" | "object";
  enum?: Array<string | number | boolean>;
  anyOf?: PropSchema[];
  items?: PropSchema;
  properties?: Record<string, PropSchema>;
  required?: string[];
  additionalProperties?: boolean | PropSchema;
  $ref?: string;
  /** node: text or a component · element: a component only · icon: an IconName · date: an ISO string → Date · action: a handler bound with { "$action" }. */
  "x-kind"?: "node" | "element" | "icon" | "date" | "action";
  "x-nullable"?: boolean;
  "x-icon"?: boolean;
  "x-values"?: Array<string | number | boolean>;
  /** Action parameters; `json` says whether the renderer forwards the value (true) or only the event (false). */
  params?: Array<{ name: string; type: string; json: boolean }>;
  /** The prop is required (an action is never required to be in the spec: the renderer emits it). */
  "x-required"?: boolean;
  "x-synthesized"?: boolean;
  "x-html"?: boolean;
  default?: unknown;
  description?: string;
};

export type Binding = { prop: string; handler: string; auto?: boolean; initial?: string };

export type CatalogComponent = {
  name: string;
  slug: string;
  folder: string;
  status: "stable" | "verified" | "experimental";
  chrome?: boolean;
  import: string;
  purpose: string;
  use: string[];
  avoid: string[];
  description: string;
  props: Record<string, PropSchema>;
  requiredActions: string[];
  bindings: Binding[];
  excluded: string[];
  /** Required props the catalog cannot express (the component is experimental until it offers a JSON way). */
  unavailable?: string[];
};

export type CatalogGuideline = { title: string; file: string; do: string[]; dont: string[]; rules: string[] };

export type Catalog = {
  version: string;
  spec: { format: string; version: number; markers: string[] };
  statuses: Record<string, string>;
  excludedPropNames: string[];
  components: Record<string, CatalogComponent>;
  guidelines: Record<string, CatalogGuideline>;
  $defs: Record<string, PropSchema>;
};
